/**
 * @param {number} rowsCount
 * @param {number} colsCount
 * @return {Array<Array<number>>}
 */
Array.prototype.snail = function(rowsCount, colsCount) {
    // `this` is the 1D array; invalid shape -> empty array
    if (rowsCount * colsCount !== this.length) return [];

    // rowsCount independent rows (Array.from avoids sharing one row via fill([]))
    const res = Array.from({ length: rowsCount }, () => new Array(colsCount));

    for (let i = 0; i < this.length; i++) {
        const col = Math.floor(i / rowsCount);   // which column this element lands in
        const k = i % rowsCount;                 // position within that column's pass
        // even column: top-down (row = k); odd column: bottom-up (row = rowsCount-1-k)
        const row = col % 2 === 0 ? k : rowsCount - 1 - k;
        res[row][col] = this[i];
    }
    return res;
};

/**
 * const arr = [1,2,3,4];
 * arr.snail(1,4); // [[1,2,3,4]]
 */
